'use strict';

// MODULES //

import isnan from '@stdlib/math-base-assert-is-nan';


// VARIABLES //

// (π^2/16) - (1/2):
var SCALAR = 0.11685027506808487;


// MAIN //

/**
* Returns the variance for an anglit distribution with location `mu` and scale `sigma`.
*
* @param {number} mu - location parameter
* @param {PositiveNumber} sigma - scale parameter
* @returns {PositiveNumber} variance
*
* @example
* var y = variance( 0.0, 1.0 );
* // returns ~0.117
*
* @example
* var y = variance( 2.0, 4.0 );
* // returns ~1.870
*
* @example
* var y = variance( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = variance( 0.0, NaN );
* // returns NaN
*
* @example
* var y = variance( 0.0, 0.0 );
* // returns NaN
*/
function variance( mu, sigma ) {
	if (
		isnan( mu ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}
	return ( sigma * sigma ) * SCALAR;
}


// EXPORTS //

export default variance;
